import pandas as pd

def find_invalid_ips(logs: pd.DataFrame) -> pd.DataFrame:
    pattern = r'^((25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])\.){3}(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])$'
    invalid = logs[~logs['ip'].str.match(pattern, na=False)]
    if invalid.empty:
        return pd.DataFrame(columns=['ip', 'invalid_count'])
    counts = invalid.groupby('ip').size().reset_index(name='invalid_count')
    return counts.sort_values(by=['invalid_count', 'ip'], ascending=[False, False])
